"""Template Mutator — generates variant templates via LLM when poor templates are detected."""

import json
import re
from typing import Callable, Optional

from .mutation_prompts import TEMPLATE_MUTATION_PROMPT
from .registry import EvolutionRegistry
from .schemas import Mutation

import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from decomposition.template_evolver import TemplateEvolver


class TemplateMutator:
    def __init__(
        self,
        registry: EvolutionRegistry,
        evolver: TemplateEvolver,
        llm_fn: Callable[[str], str],
    ):
        self.registry = registry
        self.evolver = evolver
        self.llm_fn = llm_fn

    def mutate_batch(self, max_mutations: int = 1) -> list[Mutation]:
        """Mutate up to N flagged templates. One active mutation at a time per component."""
        active = self.registry.get_active_mutations(component="template")
        if active:
            return []

        flagged = self.evolver.flag_poor_templates()
        if not flagged:
            return []

        mutations = []
        for tmpl in flagged[:max_mutations]:
            mutation = self._mutate_one(tmpl)
            if mutation:
                mutations.append(mutation)
        return mutations

    def _mutate_one(self, flagged: dict) -> Optional[Mutation]:
        dim = flagged["dimension"]
        original = flagged["template"]
        reasons = flagged["reasons"]

        exemplars = self.evolver.get_exemplars(dim)
        exemplars_text = self._format_exemplars(exemplars)

        prompt = TEMPLATE_MUTATION_PROMPT.format(
            dimension=dim,
            original_template=original,
            failure_reasons=", ".join(reasons),
            exemplars=exemplars_text,
            topic="{topic}",
        )

        response = self.llm_fn(prompt)
        variants = self._parse_variants(response, original)

        if len(variants) < 2:
            return None

        mutation = self.registry.create_mutation(
            component="template",
            target_path=f"dimension:{dim}",
        )

        self.registry.add_variant(mutation.id, 0, original)
        for i, v in enumerate(variants, 1):
            self.registry.add_variant(mutation.id, i, v)

        return mutation

    def _parse_variants(self, response: str, original: str) -> list[str]:
        """Parse LLM response into list of variant strings. Filters invalid ones."""
        try:
            match = re.search(r'\[.*\]', response, re.DOTALL)
            if not match:
                return []
            variants = json.loads(match.group())
        except (json.JSONDecodeError, TypeError):
            return []

        if not isinstance(variants, list):
            return []

        valid = []
        seen = {original.strip().lower()}

        for v in variants:
            if not isinstance(v, str):
                continue
            v = v.strip()
            if not self._validate_template(v):
                continue
            key = v.lower()
            if key in seen:
                continue
            seen.add(key)
            valid.append(v)

        return valid[:3]

    def _validate_template(self, template: str) -> bool:
        if "{topic}" not in template:
            return False
        if len(template) < 10 or len(template) > 200:
            return False
        if template.count("{topic}") > 2:
            return False
        return True

    def _format_exemplars(self, exemplars: list[dict]) -> str:
        if not exemplars:
            return "  (no exemplars available for this dimension)"
        lines = []
        for i, ex in enumerate(exemplars, 1):
            lines.append(
                f"  {i}. \"{ex['text']}\" (yield={ex['yield']}, parse={ex['parse_rate']})"
            )
        return "\n".join(lines)

