    ]
    evolver.get_exemplars.return_value = [
        {"text": "exemplar {topic}", "yield": 3.0, "parse_rate": 0.9}
    ]
    return evolver


def _make_llm_fn(variants: list[str]):
    def fn(prompt: str) -> str:
        return json.dumps(variants)
    return fn


def test_mutate_batch_creates_mutation(registry, mock_evolver):
    llm_fn = _make_llm_fn([
        "{topic} market TAM 2024",
        "total addressable market {topic} growth",
        "{topic} industry size revenue",
    ])
    mutator = TemplateMutator(registry=registry, evolver=mock_evolver, llm_fn=llm_fn)
    mutations = mutator.mutate_batch(max_mutations=1)
    assert len(mutations) == 1
    variants = registry.get_variants(mutations[0].id)
    assert len(variants) == 4  # 1 original + 3 mutants


def test_mutate_batch_blocked_if_active(registry, mock_evolver):
    registry.create_mutation("template", "dimension:x")
    llm_fn = _make_llm_fn(["{topic} a", "{topic} b", "{topic} c"])
    mutator = TemplateMutator(registry=registry, evolver=mock_evolver, llm_fn=llm_fn)
    assert mutator.mutate_batch() == []


def test_mutate_batch_no_flagged(registry):
    evolver = MagicMock()
    evolver.flag_poor_templates.return_value = []
    mutator = TemplateMutator(registry=registry, evolver=evolver, llm_fn=lambda p: "[]")
    assert mutator.mutate_batch() == []


def test_parse_variants_valid():
    mutator = TemplateMutator(
        registry=MagicMock(), evolver=MagicMock(), llm_fn=lambda p: ""
    )
    response = json.dumps([
        "{topic} variant A here",
        "{topic} variant B here",
        "{topic} variant C here",
    ])
    result = mutator._parse_variants(response, "original {topic}")
    assert len(result) == 3


def test_parse_variants_deduplicates():
    mutator = TemplateMutator(
        registry=MagicMock(), evolver=MagicMock(), llm_fn=lambda p: ""
    )
    response = json.dumps([
        "{topic} same thing",
        "{topic} Same Thing",  # duplicate (case insensitive)
        "{topic} different one",
    ])
    result = mutator._parse_variants(response, "original {topic}")
    assert len(result) == 2


def test_parse_variants_filters_invalid():
    mutator = TemplateMutator(
        registry=MagicMock(), evolver=MagicMock(), llm_fn=lambda p: ""
    )
    response = json.dumps([
        "no placeholder here",  # missing {topic}
        "x",  # too short
        "{topic} " + "x" * 250,  # too long
        "{topic} valid template here",
    ])
    result = mutator._parse_variants(response, "original {topic}")
    assert len(result) == 1
    assert "valid" in result[0]


def test_parse_variants_handles_bad_json():
    mutator = TemplateMutator(
        registry=MagicMock(), evolver=MagicMock(), llm_fn=lambda p: ""
    )
    assert mutator._parse_variants("not json at all", "orig") == []
    assert mutator._parse_variants("", "orig") == []


def test_validate_template():
    mutator = TemplateMutator(
        registry=MagicMock(), evolver=MagicMock(), llm_fn=lambda p: ""
    )
    assert mutator._validate_template("{topic} market size revenue 2024") is True
    assert mutator._validate_template("no placeholder") is False
    assert mutator._validate_template("{topic}") is False  # too short
    assert mutator._validate_template("{topic} {topic} {topic} x") is False  # >2 placeholders


def test_mutate_returns_none_if_too_few_variants(registry, mock_evolver):
    llm_fn = _make_llm_fn(["{topic} only one variant"])
    mutator = TemplateMutator(registry=registry, evolver=mock_evolver, llm_fn=llm_fn)
    mutations = mutator.mutate_batch()
    assert mutations == []

