"""Sandbox Runner — A/B competition framework for template variants."""

import time
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Callable, Optional

from .registry import EvolutionRegistry
from .schemas import Variant


@dataclass
class RunMetrics:
    variant_id: int
    variant_index: int
    facts_produced: int
    parse_success: float
    avg_confidence: float
    raw_response_len: int
    execution_ms: int


@dataclass
class CompetitionResult:
    mutation_id: int
    query: str
    timestamp: str
    variant_scores: dict[int, RunMetrics]
    best_variant_id: Optional[int]


class SandboxRunner:
    def __init__(
        self,
        registry: EvolutionRegistry,
        research_fn: Callable[[str], str],
        min_cases_to_judge: int = 5,
        rate_limit_seconds: float = 1.5,
    ):
        self.registry = registry
        self.research_fn = research_fn
        self.min_cases = min_cases_to_judge
        self.rate_limit = rate_limit_seconds

    def run_competition(self, mutation_id: int, query: str) -> CompetitionResult:
        """Run all variants for a mutation against the same query."""
        variants = self.registry.get_variants(mutation_id)
        results: dict[int, RunMetrics] = {}

        for variant in variants:
            metrics = self._execute_single(variant, query)
            results[variant.id] = metrics

            self.registry.log_fitness(
                variant_id=variant.id,
                case_id=f"sandbox-{mutation_id}-{_slug(query)}",
                brier=None,
                fact_yield=float(metrics.facts_produced),
                parse_success=metrics.parse_success,
            )

            if variant != variants[-1]:
                time.sleep(self.rate_limit)

        best_id = self._pick_leader(results) if results else None

        return CompetitionResult(
            mutation_id=mutation_id,
            query=query,
            timestamp=datetime.now(timezone.utc).isoformat(),
            variant_scores=results,
            best_variant_id=best_id,
        )

    def _execute_single(self, variant: Variant, query: str) -> RunMetrics:
        search_query = variant.content.replace("{topic}", query)

        start = time.time()
        try:
            raw_response = self.research_fn(search_query)
        except Exception:
            raw_response = ""
        elapsed_ms = int((time.time() - start) * 1000)

        facts, parse_ok = self._extract_facts(raw_response)

        confidences = [f.get("confidence", 0.5) for f in facts] if facts else []
        avg_conf = sum(confidences) / len(confidences) if confidences else 0.0

        return RunMetrics(
            variant_id=variant.id,
            variant_index=variant.variant_index,
            facts_produced=len(facts),
            parse_success=1.0 if parse_ok and facts else 0.0,
            avg_confidence=avg_conf,
            raw_response_len=len(raw_response),
            execution_ms=elapsed_ms,
        )

    def _extract_facts(self, response: str) -> tuple[list[dict], bool]:
        """Extract factual claims from response. Returns (facts, parse_success)."""
        if not response or len(response) < 20:
            return [], False

        facts = []
        lines = response.split("\n")
        for line in lines:
            line = line.strip()
            if not line or len(line) < 15:
                continue
            if _has_factual_signal(line):
                facts.append({
                    "fact": line[:200],
                    "confidence": _estimate_confidence(line),
                })

        return facts, len(facts) > 0

    def _pick_leader(self, results: dict[int, RunMetrics]) -> Optional[int]:
        if not results:
            return None
        scored = [
            (vid, m.facts_produced * 0.6 + m.parse_success * 0.25 + m.avg_confidence * 0.15)
            for vid, m in results.items()
        ]
        scored.sort(key=lambda x: x[1], reverse=True)
        return scored[0][0]


def _slug(text: str) -> str:
    return text[:30].replace(" ", "-").replace("/", "_")


def _has_factual_signal(line: str) -> bool:
    """Heuristic: line contains numbers, dates, or named entities."""
    import re
    if re.search(r'\d+[%$€£¥]|\$\d|USD|EUR|\d{4}', line):
        return True
    if re.search(r'\d+\.\d+|\d{1,3},\d{3}', line):
        return True
    return False


def _estimate_confidence(line: str) -> float:
    """Heuristic confidence based on specificity signals."""
    score = 0.4
    import re
    if re.search(r'\d{4}', line):
        score += 0.1
    if re.search(r'\$[\d,.]+', line):
        score += 0.15
    if re.search(r'\d+%', line):
        score += 0.1
    if len(line) > 80:
        score += 0.05
    return min(score, 0.95)

